    'hospital_alert',
    reference,
    jsonb_build_object(
      'hospital_id',target_hospital,
      'source',tg_table_name,
      'status',new_status,
      'event_key',tg_table_name || ':' || clock_timestamp()::text
    )
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.notify_laboratory_result_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
